#include <cstdio>
#include <vector>
#include <queue>
#include <cstring>
#include <cctype>

using namespace std;

const int INF = 12345678;

struct Node {
    int i, j, no;
};

struct Cap {
    int no[1000];
    int ind;
    int fl;
};

Cap caps[100][100];
vector<int> v[1000];
int n, t;
int left[1000], right[1000], col[1000];
char grid[1000][1000], grid1[1000][1000];
int d[1000][1000], d1[1000][1000];
queue<Node> q;

void bfs(Node s);
void bfst(Node s);
int match(int n);
bool dfs(int s);

int main() {
    int i, j, k, l;
    Node temp, temp1;

    scanf("%d %d", &n, &t);

    for (i = 0; i <= n; ++i)
        for (j = 0; j <= n; ++j)
            d[i][j] = INF;

    for (i = 0; i < n; ++i)
        scanf("%s", grid[i]);

    for (i = 0; i < n; ++i)
        scanf("%s", grid1[i]);

    for (i = 0; i < n; ++i) {
        for (j = 0; j < n; ++j) {
            if (grid[i][j] == 'Z') {
                Node temp = {i, j, 0};
                bfs(temp);
            }
        }
    }

    int mark = 1;
    for (i = 0; i < n; ++i) {
        for (j = 0; j < n; ++j) {
            if (isdigit(grid1[i][j])) {
                int k = grid1[i][j] - '0';
                if (k > 0) caps[i][j].fl = 1;
                caps[i][j].ind = k;
                for (int l = 1; l <= k; ++l) {
                    caps[i][j].no[l] = mark++;
                }
            }
        }
    }

    mark = 1;
    for (i = 0; i < n; ++i) {
        for (j = 0; j < n; ++j) {
            if (isdigit(grid[i][j])) {
                int k = grid[i][j] - '0';
                for (int l = 1; l <= k; ++l) {
                    Node temp = {i, j, mark++};
                    bfst(temp);
                }
            }
        }
    }

    printf("%d\n", match(mark - 1));
    return 0;
}

bool dfs(int s) {
    if (col[s]) return false;
    col[s] = 1;
    for (size_t i = 0; i < v[s].size(); ++i) {
        int k = v[s][i];
        if (left[k] == -1) {
            left[k] = s;
            right[s] = i;
            return true;
        } else if (dfs(left[k])) {
            left[k] = s;
            right[s] = i;
            return true;
        }
    }
    return false;
}

int match(int n) {
    memset(left, -1, sizeof(left));
    memset(right, -1, sizeof(right));
    int res = 0;
    bool done;
    do {
        done = true;
        memset(col, 0, sizeof(col));
        for (int i = 1; i <= n; ++i) {
            if (right[i] == -1 && dfs(i))
                done = false;
        }
    } while (!done);
    for (int i = 1; i <= n; ++i)
        if (right[i] != -1) ++res;
    return res;
}

void bfs(Node s) {
    for (int i = 0; i <= n; ++i)
        for (int j = 0; j <= n; ++j)
            d[i][j] = INF;
    int i = s.i, j = s.j;
    d[i][j] = 0;
    q = queue<Node>();
    q.push(s);
    while (!q.empty()) {
        Node temp = q.front(); q.pop();
        i = temp.i; j = temp.j;
        if (grid[i][j] == 'Y') continue;
        if (grid[i][j] == 'Z') continue;
        if (caps[i][j].fl == 1) {
            if (d[i][j] <= t && d[i][j] <= d[i][j]) {
                for (int l = 1; l <= caps[i][j].ind; ++l) {
                    v[s.no].push_back(caps[i][j].no[l]);
                }
            }
        }
        if (d[i][j] >= d[i][j]) continue;
        static const int di[] = {1, -1, 0, 0};
        static const int dj[] = {0, 0, 1, -1};
        for (int dir = 0; dir < 4; ++dir) {
            int ni = i + di[dir], nj = j + dj[dir];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                if (d[ni][nj] > d[i][j] + 1) {
                    d[ni][nj] = d[i][j] + 1;
                    q.push({ni, nj, 0});
                }
            }
        }
    }
}

void bfst(Node s) {
    for (int i = 0; i <= n; ++i)
        for (int j = 0; j <= n; ++j)
            d1[i][j] = INF;
    int i = s.i, j = s.j;
    d1[i][j] = 0;
    queue<Node> q2;
    q2.push(s);
    while (!q2.empty()) {
        Node temp = q2.front(); q2.pop();
        i = temp.i; j = temp.j;
        if (grid[i][j] == 'Y') continue;
        if (grid[i][j] == 'Z') continue;
        if (caps[i][j].fl == 1) {
            if (d1[i][j] <= t && d1[i][j] <= d[i][j]) {
                for (int l = 1; l <= caps[i][j].ind; ++l) {
                    v[s.no].push_back(caps[i][j].no[l]);
                }
            }
        }
        if (d1[i][j] >= d[i][j]) continue;
        static const int di[] = {1, -1, 0, 0};
        static const int dj[] = {0, 0, 1, -1};
        for (int dir = 0; dir < 4; ++dir) {
            int ni = i + di[dir], nj = j + dj[dir];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                if (d1[ni][nj] > d1[i][j] + 1) {
                    d1[ni][nj] = d1[i][j] + 1;
                    q2.push({ni, nj, 0});
                }
            }
        }
    }
}
